    __shared__ double s_yij[36];
    __shared__ double s_zij[36];
    constexpr int NROOTS = 3;

    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int thread_id = 64 * gout_id + sq_id;
    int threads = 256;
    constexpr int nsq_per_block = 64;
