extern "C" __global__ void __launch_bounds__(256, 3)
k2_2021_mb3(KARGS2)
{
    __shared__ double s_aij[36];
    __shared__ double s_iaij[36];
    __shared__ double s_ajaij[36];
    __shared__ double s_xij[36];
    __shared__ double s_yij[36];
    __shared__ double s_zij[36];
    constexpr int NROOTS = 3;

    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int thread_id = 64 * gout_id + sq_id;
    int threads = 256;
    constexpr int nsq_per_block = 64;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    __shared__ int ntasks, pair_ij;
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
    }
    __syncthreads();
    fill_vk_tasks2(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff);
    if (ntasks == 0) {
        if (thread_id == 0) {
            pair_ij = atomicAdd(head, 1);
        }
        __syncthreads();
        continue;
    }

    constexpr int g_size = 18;

    extern __shared__ double shared_memory[];
    double *rlrk = shared_memory + sq_id;
    double *Rpq = shared_memory + nsq_per_block * 3 + sq_id;
    double *akl_cache = shared_memory + nsq_per_block * 6 + sq_id;
    double *fac_ijkl = shared_memory + nsq_per_block * 9 + sq_id;
    double *gx = shared_memory + nsq_per_block * 10 + sq_id;
    double *rw = shared_memory + nsq_per_block * (g_size*3+10) + sq_id;
    double *cicj_cache = shared_memory + nsq_per_block * (g_size*3+NROOTS*2+10);

    __shared__ int ish;
    __shared__ int jsh;
    __shared__ double ri[3];
    __shared__ double rjri[3];
    __shared__ double *expi;
    __shared__ double *expj;
    if (thread_id == 0) {
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
        expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a;
    int jprim = jprim_a;
    double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
    double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
    double xjxi = rjri[0];
    double yjyi = rjri[1];
    double zjzi = rjri[2];
    double rr_ij = xjxi*xjxi + yjyi*yjyi + zjzi*zjzi;
    for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
        double ai = expi[ij/jprim];
        double aj = expj[ij%jprim];
        double aij = ai + aj;
        double iaij = 1. / aij;
        double aj_aij = aj * iaij;
        s_aij  [ij] = aij;
        s_iaij [ij] = iaij;
        s_ajaij[ij] = aj_aij;
        s_xij  [ij] = ri[0] + xjxi * aj_aij;
        s_yij  [ij] = ri[1] + yjyi * aj_aij;
        s_zij  [ij] = ri[2] + zjzi * aj_aij;
        cicj_cache[ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
